const fs=require('fs'),crypto=require('crypto');
const {chromium}=require('/home/ramin/.npm/_npx/fd3bca3c548369c0/node_modules/playwright');
const root='/home/ramin/kidsmap',base='http://127.0.0.1:8763/docs/task33/design/';
const result={role:'browser-qa independent specialist /root/stage03_review',mode:'PROTOTYPES ONLY',generated_at:new Date().toISOString(),matrix:[],flows:[],errors:[],hashes:{}};
for(const f of ['shared03/prototype.js','shared03/prototype.css',...['admin','public'].flatMap(a=>fs.readdirSync(`${root}/docs/task33/design/${a}`).filter(f=>f.endsWith('.html')).map(f=>`${a}/${f}`))])result.hashes[f]=crypto.createHash('sha256').update(fs.readFileSync(`${root}/docs/task33/design/${f}`)).digest('hex');
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});result.browser=browser.version();const page=await browser.newPage();page.on('pageerror',e=>result.errors.push({type:'page',text:String(e)}));page.on('console',e=>{if(e.type()==='error')result.errors.push({type:'console',text:e.text()})});page.on('requestfailed',r=>result.errors.push({type:'requestfailed',page:page.url(),url:r.url(),error:r.failure()?.errorText}));page.on('response',r=>{if(r.status()>=400)result.errors.push({type:'HTTP',url:r.url(),status:r.status()})});await page.route('**/*',route=>{if(new URL(route.request().url()).hostname!=='127.0.0.1'){result.errors.push({type:'external',url:route.request().url()});return route.abort()}return route.continue()});
async function load(a,s,q='',width=390){await page.setViewportSize({width,height:900});await page.goto(`${base}${a}/${s}.html?${new URLSearchParams({lang:"ru",...Object.fromEntries(new URLSearchParams(q))})}`);await page.evaluate(()=>document.fonts.ready);await page.locator('h1').waitFor()}
async function flow(name,fn){try{result.flows.push({name,status:'PASS',evidence:await fn()})}catch(e){result.flows.push({name,status:'FAIL',error:String(e)})}}
if(!process.env.REVIEW_SKIP_MATRIX)for(const [area,screens]of Object.entries({admin:['index','organization','place','groups','review','transfer'],public:['index','catalog','organization','place','activity','events','event']}))for(const screen of screens)for(const lang of ['az','ru','en'])for(const width of [320,360,390,768,1024,1280,1440]){await load(area,screen,`lang=${lang}`,width);const layout=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,lang:document.documentElement.lang,h1:document.querySelector('h1').textContent,duplicates:[...document.querySelectorAll('[id]')].map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i)}));result.matrix.push({area,screen,lang,width,...layout,status:layout.scroll<=width&&layout.lang===lang&&!layout.duplicates.length?'PASS':'FAIL'})}
await flow('new-review-axes',async()=>{await load('admin','review','state=new');const axes=await page.locator('.axes').innerText();if(axes.includes('Опубликовано')||axes.includes('Есть владелец'))throw Error('new proposal wrong axes');return {axes,newText:await page.locator('.diff-row').first().innerText()}});
await flow('park-only-map',async()=>{await load('public','catalog');await page.locator('#search').fill('Тихий сад');await page.locator('#catalog-map').click();const disabled=await page.locator('#venue').isDisabled();if(!disabled)throw Error('park-only venue must be disabled');return {disabled,count:await page.locator('#result-count').innerText(),venue:await page.locator('#venue-results').innerText()}});
await flow('network-search-results',async()=>{await load('public','catalog');await page.locator('#search').fill('Сеть «Открытие»');const rows=await page.locator('#catalog-results [data-place]:visible').count();if(rows!==1)throw Error('unrelated network result');return {rows,count:await page.locator('#result-count').innerText(),results:await page.locator('#catalog-results').innerText()}});
for(const state of ['volunteer','program','new'])await flow('review-dialog-'+state,async()=>{await load('admin','review','state='+state);await page.locator('#approve').click();const text=await page.locator('#dialog-copy').innerText();if(await page.evaluate(()=>document.activeElement.id)!=='dialog-close')throw Error('initial focus');await page.keyboard.press('Shift+Tab');if(await page.evaluate(()=>document.activeElement.id)!=='dialog-confirm')throw Error('trap');await page.keyboard.press('Escape');if(await page.evaluate(()=>document.activeElement.id)!=='approve')throw Error('restore');await page.locator('#reject').click();if(await page.evaluate(()=>document.activeElement.id)!=='review-note')throw Error('reject focus');await page.locator('#review-note').fill('Уточните данные');await page.locator('#reject').click();await page.locator('#dialog-confirm').click();return {copy:text,feedback:await page.locator('#feedback').innerText()}});
await flow('conflict-disabled',async()=>{await load('admin','review','state=conflict');if(!await page.locator('button[disabled]').isDisabled())throw Error('not disabled');return await page.locator('#blocked').innerText()});
await flow('transfer-negative-positive',async()=>{await load('admin','transfer');await page.locator('#transfer').click();if(await page.evaluate(()=>document.activeElement.id)!=='transfer-check')throw Error('validation focus');await page.locator('#transfer-check').check();await page.locator('#transfer').click();const copy=await page.locator('#dialog-copy').innerText();await page.locator('#dialog-confirm').click();return copy});
await flow('calendar-filter-preserved',async()=>{await load('public','events','view=calendar');await page.locator('#event-format').selectOption('online');await page.locator('[data-date="2026-10-03"]').click();const count=await page.locator('#event-results .event-row').count();await page.locator('#event-list').click();await page.locator('#event-calendar').click();await page.reload();if(await page.locator('#event-format').inputValue()!=='online'||count!==1)throw Error('filter lost');return {rows:count,url:page.url(),selected:await page.locator('#day-heading').innerText()}});
await flow('calendar-beyond-november-reload',async()=>{await load('public','events','view=calendar&month=2026-11');await page.locator('#next-month').click();const before=await page.locator('#month-label').innerText();await page.reload();const after=await page.locator('#month-label').innerText();if(before!==after)throw Error('month lost');return {before,after,url:page.url()}});
for(const event of ['online','canceled','past'])await flow('event-'+event,async()=>{await load('public','event','event='+event);return await page.locator('main').innerText()});
for(const screen of ['place','activity','organization','event'])await flow('missing-long-'+screen,async()=>{await load('public',screen,'missing=1&long=1&lang=en',320);return {fallback:await page.locator('.notice').first().innerText(),scroll:await page.evaluate(()=>document.documentElement.scrollWidth)}});
await flow('org-activity-rating-separate',async()=>{await load('public','organization');const orgText=await page.locator('main').innerText();await load('public','activity');return {orgNoAggregate:orgText.includes('нет общего рейтинга'),activityNoInheritedRating:(await page.locator('main').innerText()).includes('Оценка места сюда не переносится')}});
await flow('independent-shared-venue',async()=>{await load('public','catalog');await page.locator('#catalog-map').click();await page.locator('#venue').click();const count=await page.locator('[data-venue-place]:visible').count();await page.locator('#activity-filter').selectOption('robotics');await page.locator('#venue').click();const filtered=await page.locator('[data-venue-place]:visible').count();if(count!==2||filtered!==1)throw Error('wrong venue filters');return {count,filtered}});
await flow('az-calendar-human-month',async()=>{await load('public','events','lang=az&view=calendar');const month=await page.locator('#month-label').innerText();if(/M\d/.test(month))throw Error('AZ ICU technical label');return month});
await flow('calendar-category-age-locale',async()=>{await load('public','events','view=calendar');await page.locator('#event-category').selectOption('science');await page.locator('#event-age').selectOption('8');await page.locator('.locale a').filter({hasText:'EN'}).click();await page.waitForLoadState('load');await page.evaluate(()=>document.fonts.ready);if(await page.locator('#event-category').inputValue()!=='science'||await page.locator('#event-age').inputValue()!=='8')throw Error('filters lost');return page.url()});
await flow('studio-h1',async()=>{await load('public','place','sample=studio');const h1=await page.locator('h1').innerText();if(!h1.includes('студия'))throw Error('studio heading '+h1);return h1});
await flow('narimanov-address-activity',async()=>{await load('public','place','sample=narimanov');const address=await page.locator('.facts dd').first().innerText(),activity=await page.locator('h3').first().innerText();const href=await page.locator('a.feature-link').filter({hasText:'Посмотреть местные условия'}).getAttribute('href');if(address.includes('Ясамал')||activity.includes('Ясамал')||!href.includes('sample=narimanov'))throw Error(JSON.stringify({address,activity,href}));await page.locator('a.feature-link').filter({hasText:'Посмотреть местные условия'}).click();await page.waitForLoadState('load');await page.evaluate(()=>document.fonts.ready);if(!(await page.locator('h1').innerText()).includes('Нариманов'))throw Error('activity identity lost');return {address,activity,href}});
await flow('narimanov-h1',async()=>{await load('public','place','sample=narimanov');const h1=await page.locator('h1').innerText();if(!h1.includes('Нариманов'))throw Error('branch heading '+h1);return h1});
await flow('organization-narimanov-chain',async()=>{await load('public','organization');const card=page.locator('.place-card').filter({hasText:'Нариманов'});const sub=await card.locator('.sub').innerText();if(!sub.includes('Нариманов')||sub.includes('Ясамал'))throw Error('incorrect branch card '+sub);await card.locator('a').click();await page.waitForLoadState('load');await page.evaluate(()=>document.fonts.ready);await page.locator('a.feature-link').filter({hasText:'Посмотреть местные условия'}).click();await page.waitForLoadState('load');await page.evaluate(()=>document.fonts.ready);if(!(await page.locator('h1').innerText()).includes('Нариманов'))throw Error('forward identity');await page.locator('a.feature-link').filter({hasText:'Открытие · Нариманов'}).click();await page.waitForLoadState('load');await page.evaluate(()=>document.fonts.ready);if(!(await page.locator('h1').innerText()).includes('Нариманов'))throw Error('back identity');return {sub,url:page.url()}});
await flow('group-explicit-save',async()=>{await load('admin','groups');if(!await page.locator('#group-name').getAttribute('readonly')===null){}const readonly=await page.locator('#group-name').evaluate(e=>e.readOnly);if(!readonly)throw Error('group name editable');await page.locator('#group-price').fill('90');await page.locator('#group-schedule').fill('Суббота 17:00');await page.locator('#save-group').click();return {readonly,feedback:await page.locator('#feedback').innerText()}});
fs.writeFileSync('/tmp/task33-review-result.json',JSON.stringify(result,null,2));await browser.close();if(result.errors.length||result.matrix.some(r=>r.status!=='PASS')||result.flows.some(r=>r.status!=='PASS'))throw Error('Strict review acceptance failed; see /tmp/task33-review-result.json');console.log(JSON.stringify({matrix:result.matrix.length,matrix_fail:result.matrix.filter(r=>r.status!=='PASS'),flows:result.flows.map(f=>({name:f.name,status:f.status,evidence:f.name.includes('axes')||f.name.includes('map')||f.name.includes('reload')||f.name.includes('search')?f.evidence:undefined})),errors:result.errors}));})().catch(e=>{console.error(e);process.exit(1)});
